/* Persen Apparel owner portal. Requires authenticated admin membership verified by DB RLS. */
'use strict';
const root=document.getElementById('owner-app');
const LOGO='assets/persen-logo.png';
const STOREFRONT=(window.PERSEN_CONFIG?.storefrontUrl||'https://persenapparel.com').replace(/\/$/,'');
const CONTENT_KEYS=[
 ['hero_photo_url','Homepage showcase photo URL','Upload below, then copy the URL here to show a real photo on the homepage'],
 ['hero_photo_alt','Homepage photo description','Describe the image for accessibility'],
 ['announcement','Announcement bar','The small message above the navigation'],
 ['hero_kicker','Homepage eyebrow','Short text above the main headline'],
 ['hero_title','Homepage headline','Use a line break for multiple lines'],
 ['hero_description','Homepage description','The main paragraph of your homepage'],
 ['home_cta','Main button text','Text on the Design Lab button'],
 ['featured_title','Apparel section title','Title above the product categories'],
 ['favorites_title','Customer Favorites headline','Heading shown above the featured products'],
 ['favorites_description','Customer Favorites description','Small description above the selected products'],
 ['sports_title','Sports page headline','Main heading on Sports & Teams'],
 ['sports_intro','Sports page introduction','Text under the sports-page headline'],
 ['sports_section_title','Sports section heading','Heading on the sports service page'],
 ['sports_section_description','Sports section paragraph','Main explanation of services for sports teams'],
 ['business_title','Business page headline','Main heading on the Businesses page'],
 ['business_intro','Business page introduction','Text under the business-page headline'],
 ['business_section_title','Business section heading','Heading on the business service page'],
 ['business_section_description','Business section paragraph','Main explanation of business apparel'],
 ['about_text','About page paragraph','Brief description of Persen Apparel'],
 ['contact_email','Contact email','Used for contact and quote requests']
];
const ORDER_STATUSES=['Received','Artwork review','Awaiting proof','Approved','In production','Ready for pickup','Shipped','Completed','Cancelled'];
const QUOTE_STATUSES=['New','Reviewing','Awaiting customer','Approved','Closed'];
const FULFILLMENT=['To be confirmed','Local pickup','Shipping'];
const KINDS=['tee','hoodie','crew','zip','polo','tank','sweats','shorts'];
const CHANNELS=['Phone','Instagram','Email','Text','In person','Website','Other'];
const PAYMENT_METHODS=['Cash','Check','Bank transfer','Card (external)','Other'];
const v4=window.PersenIntelligence;
let seasonalEditing='', authUser=null, owner=false, view='overview', data={products:[],content:[],quotes:[],orders:[],contacts:[],stock:[],invoices:[],messages:[],tasks:[],payments:[],activities:[],manualOrders:[],analytics:[],agreements:[],agreementsIssue:"",guestQuotes:[],guestQuotesIssue:""};
const safe=x=>String(x??'').replace(/[&<>"']/g,y=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[y]));
const msg=(text)=>{let t=document.getElementById('owner-toast');t.textContent=text;t.style.display='block';clearTimeout(window._ownerToastTimeout);window._ownerToastTimeout=setTimeout(()=>t.style.display='none',4300)};
const d=x=>x?new Date(x).toLocaleDateString():'—';
const badge=x=>`<span class="owner-pill">${safe(x)}</span>`;
const options=(arr,current)=>arr.map(v=>`<option value="${safe(v)}" ${v===current?'selected':''}>${safe(v)}</option>`).join('');
const header=()=>`<header class="owner-header"><div class="owner-logo"><img src="${LOGO}" alt="Persen Apparel official logo"><span>PERSEN <span style="color:#83b5ff">COMMAND</span></span></div><div class="owner-header-right"><span>${safe(authUser.email)}</span><button class="btn ghost sm" data-click="signout">Sign Out</button></div></header>`;
function login(message=''){root.innerHTML=`<div class="owner-login"><img width="75" height="75" src="${LOGO}" alt="Persen Apparel logo"><h1>Persen Command Center.</h1><p>A private workspace for running your custom apparel business. Sign in with an owner-approved account.</p>${message?`<div class="owner-flag">${safe(message)}</div>`:''}${!PA?.ready?'<div class="owner-flag">Backend not connected. Add your Supabase project URL and publishable key to config.js, then follow SETUP.md.</div>':''}<form id="owner-login"><label for="owner-email">EMAIL</label><input required class="field" id="owner-email" type="email" autocomplete="email" name="email"><label for="owner-password">PASSWORD</label><input required class="field" id="owner-password" type="password" autocomplete="current-password" name="password"><button class="btn primary wide" type="submit" style="margin-top:22px" ${!PA?.ready?'disabled':''}>Secure Sign In</button></form><p style="margin-top:22px">Customer? <a style="color:#1761d2;font-weight:800" href="${STOREFRONT}/#/account">Go to the customer account page</a></p></div>`}
async function init(){if(!PA?.ready){login();return}try{authUser=await PA.me();owner=await PA.isAdmin(authUser);if(!authUser){login();return}if(!owner){login('Your account is not on the approved owner/employee list. Sign in with an authorized account.');return}await refresh()}catch(err){login('Unable to connect to your database: '+err.message)}}
async function loadAnalytics(){try{return await PA.checked(PA.db.from('site_analytics_events').select('occurred_at,event_type,page_path,session_id').order('occurred_at',{ascending:false}).limit(5000))}catch{return []}}
async function loadAgreementsSafe(){try{return {rows:await PersenAgreements.load(),issue:""}}catch(err){return {rows:[],issue:err.message}}}
async function loadGuestQuotesSafe(){try{return {rows:await PA.checked(PA.db.from('guest_quote_requests').select('*').order('created_at',{ascending:false}).limit(300)),issue:""}}catch(err){return {rows:[],issue:err.message}}}
async function refresh(){if(!owner)return;try{
 const [products,content,quotes,orders,contacts,stock,invoices,messages,tasks,payments,activities,manualOrders,analytics,agreementResult,guestResult]=await Promise.all([
  PA.checked(PA.db.from('products').select('*').order('sort_order')),
  PA.checked(PA.db.from('site_content').select('*')),
  PA.checked(PA.db.from('quote_requests').select('*').order('created_at',{ascending:false}).limit(300)),
  PA.checked(PA.db.from('customer_orders').select('*').order('created_at',{ascending:false}).limit(300)),
  PA.checked(PA.db.from('customer_contacts').select('*').order('updated_at',{ascending:false}).limit(300)),
  PA.checked(PA.db.from('stock_items').select('*').order('sku').limit(500)),
  PA.checked(PA.db.from('business_invoices').select('*').order('created_at',{ascending:false}).limit(300)),
  PA.checked(PA.db.from('support_messages').select('*').order('created_at',{ascending:false}).limit(300)),
  PA.checked(PA.db.from('business_tasks').select('*').order('due_date',{ascending:true}).limit(300)),
  PA.checked(PA.db.from('invoice_payments').select('*').order('received_on',{ascending:false}).limit(1000)),
  PA.checked(PA.db.from('customer_activities').select('*').order('occurred_at',{ascending:false}).limit(1000)),
  PA.checked(PA.db.from('manual_business_orders').select('*').order('created_at',{ascending:false}).limit(300)),
  loadAnalytics(),
  loadAgreementsSafe(),
  loadGuestQuotesSafe()]);
 data={products,content,quotes,orders,contacts,stock,invoices,messages,tasks,payments,activities,manualOrders,analytics,agreements:agreementResult.rows,agreementsIssue:agreementResult.issue,guestQuotes:guestResult.rows,guestQuotesIssue:guestResult.issue};render()
}catch(err){msg('Could not load live records: '+err.message);render()}}
function render(){if(!owner)return login('Not authorized as a site administrator.');const tabs=[['overview','Overview'],['intelligence','Intelligence'],['messages','Inbox'],['contacts','Customers'],['quotes','Quotes'],['estimates','Estimates'],['orders','Orders'],['stock','Inventory'],['invoices','Invoices'],['tasks','Follow-Ups'],['products','Apparel'],['content','Website Editor'],['seasonal','Seasonal Studio'],['analytics','Analytics']];root.innerHTML=header()+`<main class="owner-main"><div class="owner-hero"><div><div class="eyebrow">PRIVATE OWNER DASHBOARD</div><h1>Persen Command Center<span style="color:#2875e8">.</span></h1><p>Manage your website and customer projects anywhere, from a phone or computer.</p></div><a class="btn primary sm" href="${STOREFRONT}" target="_blank" rel="noopener noreferrer">Open storefront ↗</a></div><nav class="owner-nav" aria-label="Dashboard sections">${tabs.map(([k,t])=>`<button data-click="view" data-id="${k}" class="${view===k?'active':''}">${t}</button>`).join('')}</nav>${view==='overview'?overview():view==='intelligence'?intelligenceView():view==='quotes'?quotesView()+guestQuotesView():view==='estimates'?invoicesView('Estimate'):view==='orders'?ordersView():view==='products'?productsView():view==='content'?contentView():view==='seasonal'?seasonalView():view==='analytics'?analyticsView():view==='contacts'?contactsView():view==='stock'?stockView():view==='invoices'?invoicesView():view==='tasks'?tasksView():messagesView()}<p class="owner-mini" style="margin-top:20px">Account access and data permissions are enforced by Supabase. Updates affect the live storefront when both sites use the same configured database. No payment card details are collected; payment entries are manual owner records.</p></main>`}
function analyticsView(){
 const events=(data.analytics||[]).filter(e=>new Date(e.occurred_at).getTime()>=Date.now()-30*86400000), now=Date.now(), recent=events.filter(e=>new Date(e.occurred_at).getTime()>=now-7*86400000);
 const count=(arr,type)=>arr.filter(e=>e.event_type===type).length;
 const sessions=new Set(recent.filter(e=>e.event_type==='page_view').map(e=>e.session_id)).size;
 const pages=Object.entries(recent.filter(e=>e.event_type==='page_view').reduce((acc,e)=>(acc[e.page_path]=(acc[e.page_path]||0)+1,acc),{})).sort((a,b)=>b[1]-a[1]).slice(0,10);
 const max=Math.max(1,...pages.map(x=>x[1]));
 return `<section class="owner-section"><h2>Website Analytics</h2><p>First-party website activity stored in your Supabase database. No Google Analytics needed. Last 7 days, based on up to 5,000 events from the last 30 days.</p><div class="owner-metrics"><div class="owner-metric"><span>Page views</span><strong>${count(recent,'page_view')}</strong></div><div class="owner-metric"><span>Browser sessions (approx.)</span><strong>${sessions}</strong></div><div class="owner-metric"><span>Design Lab opens</span><strong>${count(recent,'design_lab_opened')}</strong></div><div class="owner-metric"><span>Quote page opens</span><strong>${count(recent,'quote_started')}</strong></div></div><h3>Most visited pages</h3><div class="owner-chart">${pages.map(([path,n])=>`<div class="owner-chart-row"><span>${safe(path)}</span><div class="owner-chart-track"><div class="owner-chart-fill" style="width:${100*n/max}%"></div></div><strong>${n}</strong></div>`).join('')||'<p>No recorded visits yet.</p>'}</div><p class="owner-mini">These are approximate counts, not verified people or sales. Browsers blocking scripts or database calls will not appear. No IP addresses or customer names are stored in this table. Public analytics ingestion is susceptible to artificial traffic; do not use these numbers for billing.</p></section>`;
}
function overview(){const active=data.products.filter(p=>p.active).length,openQuotes=data.quotes.filter(q=>!['Closed','Approved'].includes(q.status)).length,live=data.orders.filter(o=>!['Completed','Cancelled'].includes(o.status)).length;const counts=Object.fromEntries(QUOTE_STATUSES.map(k=>[k,data.quotes.filter(x=>x.status===k).length]));const max=Math.max(1,...Object.values(counts));return `<div class="v3-alert-strip"><strong>${data.messages.filter(x=>x.status==='New').length}</strong> unread messages · <strong>${data.guestQuotes.filter(x=>x.status==='New').length}</strong> new guest quotes · <strong>${data.stock.filter(x=>x.quantity<=x.reorder_at).length}</strong> low-stock SKUs · <strong>${data.invoices.filter(x=>x.status==='Draft').length}</strong> draft invoices · <strong>${data.contacts.length}</strong> customer records · <strong>${(data.tasks||[]).filter(t=>t.status!=='Done').length}</strong> open follow-ups</div><div class="owner-metrics"><div class="owner-metric"><span>Quote requests</span><strong>${data.quotes.length}</strong><p>Latest 300 records</p></div><div class="owner-metric"><span>Quotes in progress</span><strong>${openQuotes}</strong><p>Awaiting action / review</p></div><div class="owner-metric"><span>Orders in progress</span><strong>${live}</strong><p>Not completed or cancelled</p></div><div class="owner-metric"><span>Live apparel products</span><strong>${active}</strong><p>Visible in the customer catalog</p></div></div><div class="owner-grid"><section class="owner-section"><h2>Quote pipeline</h2><p>Live quote counts for records loaded from your database. No fictional sales or profit figures.</p><div class="owner-chart">${QUOTE_STATUSES.map(k=>`<div class="owner-chart-row"><span>${safe(k)}</span><div class="owner-chart-track"><div class="owner-chart-fill" style="width:${100*counts[k]/max}%"></div></div><strong>${counts[k]}</strong></div>`).join('')}</div></section><section class="owner-section"><h2>Recently received quotes</h2>${data.quotes.length?`<div class="owner-list">${data.quotes.slice(0,4).map(q=>`<article><div class="owner-row"><h3>${safe(q.category)}</h3>${badge(q.status)}</div><p>${safe(q.name)} · Qty ${q.quantity} · ${d(q.created_at)}</p></article>`).join('')}</div>`:'<div class="owner-empty">No live quote requests yet.</div>'}<button class="btn ghost sm" data-click="view" data-id="quotes" style="margin-top:17px">Review Quotes</button></section></div><section class="owner-section"><div class="owner-row"><div><h2>Next actions</h2><p>Follow-ups with deadlines and current low-stock alerts.</p></div><button class="btn ghost sm" data-click="view" data-id="tasks">Manage Follow-Ups</button></div>${(data.tasks||[]).filter(x=>x.status!=='Done').length?`<div class="owner-list">${data.tasks.filter(x=>x.status!=='Done').slice(0,5).map(x=>`<article><div class="owner-row"><h3>${safe(x.title)}</h3>${badge(x.priority)}</div><p>${x.customer_name?safe(x.customer_name)+' · ':''}Due ${safe(x.due_date||'Not set')} · ${safe(x.status)}</p></article>`).join('')}</div>`:'<div class="owner-empty">No outstanding follow-ups.</div>'}</section><section class="owner-section"><h2>Launch status</h2><div class="owner-flag good">Database-connected: product edits, homepage text, group stores, customer accounts, saved designs, quote requests, and order statuses use live records.</div><p>Not yet integrated: Stripe payments, automatic customer emails (unless V3 webhook configured), AI support, private store passwords, production proof approvals, automated supplier sync, shipping label generation, and revenue reporting.</p></section>`}

function intelligenceView(){
 const briefing=v4.brief(data);
 const summary=`<div class="owner-metrics"><div class="owner-metric"><span>Overdue / urgent</span><strong>${briefing.urgent}</strong><p>Rules-based alerts</p></div><div class="owner-metric"><span>Follow-ups / review</span><strong>${briefing.attention}</strong><p>Messages, quotes, proofs, tasks</p></div><div class="owner-metric"><span>Low-stock SKUs</span><strong>${briefing.lowStock}</strong><p>Based on manual inventory</p></div><div class="owner-metric"><span>Invoices with balance</span><strong>${briefing.unpaid}</strong><p>Includes drafts, excludes estimates</p></div></div>`;
 const guestNew=(data.guestQuotes||[]).filter(q=>q.status==='New');const unsigned=(data.invoices||[]).filter(i=>i.document_type!=='Estimate'&&i.status!=='Void'&&!PersenAgreements.signed(data.agreements.find(a=>a.invoice_id===i.id)));
 return `<section class="owner-section"><div class="owner-row"><div><span class="eyebrow">PERSEN INTELLIGENCE CENTER · V5</span><h2>Today's business briefing</h2><p>Live rules applied to your records when this page loads. No paid AI or background notifications are running.</p></div><button class="btn ghost sm" data-click="refresh">Refresh data</button></div></section>${summary}${guestNew.length||unsigned.length?`<section class="owner-section"><h2>V5 launch workflow alerts</h2>${guestNew.length?`<article class="v4-action"><div><h3>${guestNew.length} guest quote requests need review</h3><p>Visit Quotes to respond to website visitors who do not have accounts.</p></div><button class="btn primary sm" data-click="view" data-id="quotes">Open Quotes</button></article>`:''}${unsigned.length?`<article class="v4-action"><div><h3>${unsigned.length} invoices do not have both signatures</h3><p>Collect owner and customer signatures before changing invoice status to Sent or Paid.</p></div><button class="btn primary sm" data-click="view" data-id="invoices">Open Invoices</button></article>`:''}</section>`:''}<section class="owner-section"><h2>Recommended next actions (${briefing.items.length})</h2>${briefing.items.length?`<div class="owner-list">${briefing.items.slice(0,80).map(x=>`<article class="v4-action"><div><div class="owner-row"><h3>${safe(x.title)}</h3>${badge(x.priority===3?'URGENT':x.priority===2?'ACTION':'REVIEW')}</div><p>${safe(x.detail)}</p></div><button class="btn primary sm" data-click="view" data-id="${safe(x.view)}">Open ${safe(x.view)}</button></article>`).join('')}</div>`:'<div class="owner-empty">No rule-based alerts right now. Refresh after adding customer or business records.</div>'}</section><section class="owner-section"><h2>What is automated?</h2><p>On-demand calculations for overdue invoices, quotes older than two days, unread messages, low stock, production approvals, and task deadlines. This does not send emails, run unattended, or predict sales. Use the existing inbox webhook for optional email alerts after configuration.</p></section>`;
}
function quotesView(){return `<section class="owner-section"><div class="owner-row"><div><h2>Quote inbox</h2><p>Requests submitted by registered customers. Guest requests still use email until a spam-protected server endpoint is added.</p></div><button class="btn ghost sm" data-click="refresh">Refresh</button></div>${!data.quotes.length?'<div class="owner-empty">No customer quote requests have arrived.</div>':`<div class="owner-list">${data.quotes.map(q=>`<article><div class="owner-row"><div><h3>${safe(q.category)} · ${safe(q.name)}</h3><p>${safe(q.email)} · Qty ${q.quantity} · ${d(q.created_at)} · ID ${safe(q.id.slice(0,8))}</p></div>${badge(q.status)}</div><div class="owner-detail">${safe(q.details)}</div>${q.design_summary?`<details><summary class="owner-mini">Show design summary (original artwork remains with the customer)</summary><pre class="owner-detail">${safe(JSON.stringify(q.design_summary,null,2))}</pre></details>`:''}<form class="owner-actions" data-form="quote" data-id="${q.id}"><label class="owner-mini">STATUS <select class="select" name="status">${options(QUOTE_STATUSES,q.status)}</select></label><button class="btn primary sm" type="submit">Save Status</button><button class="btn ghost sm" type="button" data-click="create-order" data-id="${q.id}">Create Tracked Order</button><a class="btn ghost sm" href="mailto:${encodeURIComponent(q.email)}?subject=${encodeURIComponent('Your Persen Apparel quote request')}">Email Customer</a></form></article>`).join('')}</div>`}</section>`}
function trackedOrdersView(){return `<section class="owner-section"><div class="owner-row"><div><h2>Order tracking</h2><p>Set the stage of production and update shipping or pickup details. Registered customers will see these updates on their accounts after refreshing.</p></div><button class="btn ghost sm" data-click="refresh">Refresh</button></div>${!data.orders.length?'<div class="owner-empty">No orders yet. Create an order from an approved quote to start tracking it.</div>':`<div class="owner-list">${data.orders.map(o=>`<article><div class="owner-row"><div><h3>${safe(o.title)}</h3><p>${d(o.created_at)} · Customer ${safe(o.user_id.slice(0,8))} · Order ${safe(o.id.slice(0,8))}</p></div>${badge(o.status)}</div><form data-form="order" data-id="${o.id}" class="owner-input-grid"><div><label class="form-label">STATUS</label><select class="select" name="status">${options(ORDER_STATUSES,o.status)}</select></div><div><label class="form-label">FULFILLMENT</label><select class="select" name="fulfillment">${options(FULFILLMENT,o.fulfillment)}</select></div><div class="wide"><label class="form-label">TRACKING REFERENCE / PICKUP NOTE</label><input class="field" name="tracking_reference" maxlength="160" value="${safe(o.tracking_reference)}" placeholder="Optional tracking code or pickup instructions"></div><div class="wide"><label class="form-label">PRIVATE PRODUCTION NOTES</label><textarea class="textarea" name="internal_notes" rows="2" maxlength="2500">${safe(o.internal_notes)}</textarea></div><div class="wide"><button class="btn primary sm" type="submit">Update Order</button></div></form></article>`).join('')}</div>`}</section>`}

function ordersView(){return trackedOrdersView()+`<section class="owner-section"><h2>Manually entered orders</h2><p>For Instagram, phone, in-person and repeat customer orders. These private orders do not appear in customer accounts.</p><form data-form="new-manual-order" class="owner-input-grid"><div><label class="form-label">CUSTOMER NAME *</label><input class="field" name="customer_name" maxlength="150" required></div><div><label class="form-label">LINK CUSTOMER RECORD</label><select class="select" name="contact_id"><option value="">Not linked</option>${data.contacts.map(c=>`<option value="${c.id}">${safe(c.full_name)}</option>`).join('')}</select></div><div><label class="form-label">PROJECT TITLE *</label><input class="field" name="title" maxlength="180" required placeholder="50 fishing team hoodies"></div><div><label class="form-label">QUANTITY</label><input class="field" type="number" name="quantity" min="1" max="100000" value="1" required></div><div><label class="form-label">DUE DATE</label><input class="field" type="date" name="due_date"></div><div><label class="form-label">STATUS</label><select class="select" name="status">${options(ORDER_STATUSES,'Received')}</select></div><div class="wide"><label class="form-label">PRIVATE NOTES</label><textarea class="textarea" name="internal_notes" maxlength="2500" rows="2"></textarea></div><div class="wide"><button class="btn primary">Add Manual Order</button></div></form></section><section class="owner-section"><h2>Offline / manual orders (${data.manualOrders.length})</h2>${data.manualOrders.length?`<div class="owner-list">${data.manualOrders.map(o=>`<article><div class="owner-row"><div><h3>${safe(o.title)}</h3><p>${safe(o.customer_name)} · Qty ${o.quantity} · Due ${safe(o.due_date||'Not set')}</p></div>${badge(o.status)}</div><form class="owner-input-grid" data-form="manual-order" data-id="${o.id}"><div><label class="form-label">STATUS</label><select class="select" name="status">${options(ORDER_STATUSES,o.status)}</select></div><div><label class="form-label">DUE DATE</label><input class="field" type="date" name="due_date" value="${safe(o.due_date||'')}"></div><div class="wide"><label class="form-label">PRODUCTION NOTES</label><textarea class="textarea" name="internal_notes" maxlength="2500" rows="2">${safe(o.internal_notes)}</textarea></div><div class="wide"><button class="btn primary sm">Update Manual Order</button></div></form></article>`).join('')}</div>`:'<div class="owner-empty">No offline orders yet.</div>'}</section>`}
function productsView(){return `<section class="owner-section"><h2>Edit apparel catalog</h2><p>Change descriptions, product visibility, garment colors, and category labels here. Product changes appear on the public store without changing the website code. All colors must be six-digit HEX codes.</p><div class="owner-list">${data.products.map(p=>`<article><form data-form="product" data-id="${safe(p.id)}"><div class="owner-row"><h3>${safe(p.name)}</h3>${badge(p.active?'LIVE':'HIDDEN')}</div><div class="owner-input-grid"><div><label class="form-label">DISPLAY NAME</label><input class="field" name="name" maxlength="120" required value="${safe(p.name)}"></div><div><label class="form-label">CATEGORY</label><input class="field" name="category" required maxlength="90" value="${safe(p.category)}"></div><div><label class="form-label">GARMENT STYLE</label><select class="select" name="kind">${options(KINDS,p.kind)}</select></div><div><label class="form-label">SORT ORDER</label><input class="field" type="number" name="sort_order" value="${p.sort_order}" min="0" max="9999"></div><div class="wide"><label class="form-label">AVAILABLE COLORS (COMMA-SEPARATED HEX)</label><input class="field" name="colors" value="${safe((p.colors||[]).join(', '))}" required></div><div class="wide"><label class="form-label">PRODUCT DESCRIPTION</label><textarea class="textarea" rows="2" name="description" maxlength="350">${safe(p.description)}</textarea></div><label class="owner-mini"><input type="checkbox" name="active" ${p.active?'checked':''} style="width:auto"> Show in storefront</label><div class="owner-actions"><button class="btn primary sm">Save Product</button></div></div></form></article>`).join('')}</div></section><section class="owner-section"><h2>Add a new apparel product</h2><p>The product ID is permanent. Use a short lowercase slug such as <code>classic-tee</code>. You can choose one of the garment silhouettes supported by the Design Lab.</p><form data-form="new-product" class="owner-input-grid"><div><label class="form-label">PRODUCT ID</label><input name="id" class="field" required pattern="[a-z0-9-]{2,40}" placeholder="vintage-tee"></div><div><label class="form-label">DISPLAY NAME</label><input name="name" class="field" required maxlength="120" placeholder="Vintage Tee"></div><div><label class="form-label">CATEGORY</label><input name="category" class="field" required maxlength="90" placeholder="T-Shirts"></div><div><label class="form-label">GARMENT STYLE</label><select class="select" name="kind">${options(KINDS,'tee')}</select></div><div class="wide"><label class="form-label">AVAILABLE COLORS</label><input class="field" name="colors" value="#101d35, #f8f9fb" required></div><div class="wide"><label class="form-label">DESCRIPTION</label><input class="field" name="description" maxlength="350"></div><div class="wide"><button class="btn primary" type="submit">Add Product</button></div></form></section>`}
function visualPreview(dict){const field=(key,fallback)=>safe(dict[key]||fallback);return `<section class="owner-section v42-editor"><h2>Visual Website Editor · V4.2</h2><p>Click the highlighted text directly in this homepage preview to edit. Select a photo from the library below, then click <strong>Publish Website Text</strong> to save changes. Preview is an approximation of the live storefront, not a full page renderer.</p><div class="v42-preview"><div class="v42-top"><strong>PERSEN APPAREL</strong><span>Shop &nbsp; Design Lab &nbsp; Get a Quote</span></div><div class="v42-announcement" data-visual-key="announcement" contenteditable="true" role="textbox" aria-label="Announcement bar" spellcheck="true">${field('announcement','Custom apparel made for Long Island')}</div><div class="v42-hero"><div><div class="v42-edit v42-kicker" data-visual-key="hero_kicker" contenteditable="true" role="textbox" aria-label="Homepage eyebrow">${field('hero_kicker','CUSTOM APPAREL · LONG ISLAND, NY')}</div><h2 class="v42-edit" data-visual-key="hero_title" contenteditable="true" role="textbox" aria-label="Homepage headline">${field('hero_title','YOUR IDEA. WORN EVERYWHERE.')}</h2><p class="v42-edit" data-visual-key="hero_description" contenteditable="true" role="textbox" aria-label="Homepage description">${field('hero_description','Custom apparel, made your way.')}</p><span class="v42-button v42-edit" data-visual-key="home_cta" contenteditable="true" role="textbox" aria-label="Main button text">${field('home_cta','Open the Design Lab')}</span></div><div class="v42-photo"><img id="v42-preview-image" src="${safe(dict.hero_photo_url||'')}" alt="${field('hero_photo_alt','Homepage showcase')}" ${dict.hero_photo_url?'':'hidden'}><span id="v42-image-placeholder" ${dict.hero_photo_url?'hidden':''}>Your homepage showcase photo<br><small>Choose a photo from the library below</small></span></div></div><div class="v42-featured v42-edit" data-visual-key="featured_title" contenteditable="true" role="textbox" aria-label="Featured apparel heading">${field('featured_title','Featured Apparel')}</div></div><p class="owner-mini">Editable text is outlined when focused. Changes remain unsaved until you publish. Sports, business and Favorites copy are editable using the Website Text fields below, rather than directly in this homepage-only preview.</p><button type="button" class="btn ghost sm" data-click="v42-reset">Reset preview to saved values</button></section>`}
function favoritesEditor(dict){const selected=String(dict.favorites_ids||'').split(',').map(x=>x.trim()).filter(Boolean);const defaults=['tee','hoodie','crew','polo'];return `<section class="owner-section"><h2>Customer Favorites · Homepage</h2><p>Choose up to four active products to feature on your homepage. These are editor-curated picks, not automatically calculated sales bestsellers. Change the headline and description under Edit Website Text above.</p><form data-form="favorites"><div class="favorites-admin-grid">${data.products.filter(p=>p.active).map(p=>`<label class="favorites-admin-option"><input type="checkbox" name="product_id" value="${safe(p.id)}" ${(selected.length?selected:defaults).includes(p.id)?'checked':''}><span><strong>${safe(p.name)}</strong><small>${safe(p.category)}</small></span></label>`).join('')}</div><p class="owner-mini">Pick 1–4 products. Customers see an illustrated product mockup and a quote-first customization action. If a product becomes hidden, it will automatically disappear from Favorites.</p><div class="owner-actions"><button class="btn primary">Publish Customer Favorites</button></div></form></section>`}
function seasonalView(){
 const S=window.PersenSeasonal,dict=Object.fromEntries(data.content.map(x=>[x.key,x.value]));
 const campaigns=S.parse(dict.seasonal_campaigns_v1),edit=campaigns.find(c=>c.slug===seasonalEditing)||null;
 const c=edit||{slug:'',title:'',subtitle:'',description:'',announcement:'',theme:'christmas',accent:'#a32736',background:'#f7efe9',start:'',end:'',imageUrl:'',featuredIds:[],published:false,limited:true,homepage:true};
 const themeOpts=Object.entries(S.THEMES).map(([key,x])=>`<option value="${safe(key)}" ${c.theme===key?'selected':''}>${safe(x.label)}</option>`).join('');
 const pick=data.products.filter(x=>x.active).map(x=>`<label class="favorites-admin-option"><input type="checkbox" name="featuredIds" value="${safe(x.id)}" ${c.featuredIds.includes(x.id)?'checked':''}><span><strong>${safe(x.name)}</strong><small>${safe(x.category)}</small></span></label>`).join('');
 return `<section class="owner-section seasonal-studio"><div class="owner-row"><div><div class="eyebrow">SEASONAL STUDIO · COMMAND CENTER</div><h2>Holiday Themes & Limited Collections</h2><p>Launch limited collections and coordinated seasonal website banners without editing code. Draft, schedule, publish, and preview campaigns. Only one active homepage campaign appears at a time; the newest start date wins.</p></div><button type="button" class="btn ghost sm" data-click="seasonal-new">+ New Campaign</button></div><div class="seasonal-presets">${Object.entries(S.THEMES).map(([k,x])=>`<button type="button" data-click="seasonal-preset" data-id="${k}" class="seasonal-preset" style="--preview-accent:${x.accent};--preview-bg:${x.background}">${safe(x.label)}</button>`).join('')}</div><div class="seasonal-list"><h3>Saved campaigns (${campaigns.length}/40)</h3>${campaigns.map(x=>`<article class="seasonal-campaign"><div><strong>${safe(x.title)}</strong> ${badge(x.published?'Published':'Draft')}<p>${safe(x.start||'Any date')} – ${safe(x.end||'No end')} · ${safe(S.THEMES[x.theme].label)} · ${x.limited?'Limited collection':'Seasonal feature'}</p></div><div class="owner-actions"><button type="button" class="btn ghost sm" data-click="seasonal-edit" data-id="${safe(x.slug)}">Edit</button><a class="btn ghost sm" target="_blank" rel="noopener noreferrer" href="${STOREFRONT}/#/collections/${encodeURIComponent(x.slug)}">Preview page ↗</a><button type="button" class="btn ghost sm" data-click="seasonal-unpublish" data-id="${safe(x.slug)}">Unpublish</button></div></article>`).join('')||'<p>No campaigns yet. Choose a preset or create one.</p>'}</div></section><section class="owner-section seasonal-studio"><h2>${edit?'Edit '+safe(edit.title):'Create a Seasonal Campaign'}</h2><p>All prices stay private. Products must already exist in the Apparel catalog. Campaigns do not create new garment designs or guarantee inventory.</p><form data-form="seasonal-save" class="owner-input-grid"><input type="hidden" name="previousSlug" value="${safe(edit?.slug||'')}"><div><label class="form-label">COLLECTION TITLE *</label><input class="field" name="title" maxlength="100" required value="${safe(c.title)}" placeholder="Long Island Winter Collection"></div><div><label class="form-label">URL SLUG *</label><input class="field" name="slug" maxlength="50" required pattern="[a-z0-9-]{3,50}" value="${safe(c.slug)}" placeholder="long-island-winter"></div><div><label class="form-label">HOLIDAY THEME</label><select class="select" name="theme" id="seasonal-theme">${themeOpts}</select></div><div><label class="form-label">BANNER ANNOUNCEMENT</label><input class="field" name="announcement" maxlength="150" value="${safe(c.announcement)}" placeholder="Winter collection · Request a quote"></div><div><label class="form-label">START DATE (OPTIONAL)</label><input class="field" name="start" type="date" value="${safe(c.start)}"></div><div><label class="form-label">END DATE (OPTIONAL)</label><input class="field" name="end" type="date" value="${safe(c.end)}"></div><div><label class="form-label">ACCENT COLOR</label><input class="field" name="accent" type="color" value="${safe(c.accent)}"></div><div><label class="form-label">BACKGROUND COLOR</label><input class="field" name="background" type="color" value="${safe(c.background)}"></div><div class="wide"><label class="form-label">COLLECTION SUBTITLE</label><input class="field" name="subtitle" maxlength="250" value="${safe(c.subtitle)}" placeholder="A limited Long Island-inspired drop"></div><div class="wide"><label class="form-label">COLLECTION STORY / DESCRIPTION</label><textarea class="textarea" name="description" maxlength="1000" rows="3">${safe(c.description)}</textarea></div><div class="wide"><label class="form-label">HERO PHOTO HTTPS URL (OPTIONAL)</label><input class="field" type="url" name="imageUrl" maxlength="500" value="${safe(c.imageUrl)}" placeholder="Use a licensed photo URL from the Website Editor photo library"></div><div class="wide"><label class="form-label">FEATURED APPAREL (UP TO 8)</label><div class="favorites-admin-grid">${pick}</div></div><div class="wide seasonal-checks"><label><input type="checkbox" name="limited" ${c.limited?'checked':''}> Show as limited collection with its own page</label><label><input type="checkbox" name="homepage" ${c.homepage?'checked':''}> Feature on homepage while campaign is active</label><label><input type="checkbox" name="published" ${c.published?'checked':''}> Publish (only visible within date window)</label></div><div class="wide seasonal-preview" style="--season-accent:${safe(c.accent)};--season-bg:${safe(c.background)}"><span>PREVIEW · PERSEN APPAREL</span><h3>${safe(c.title||'Your seasonal collection')}</h3><p>${safe(c.subtitle||'Your seasonal message will appear here.')}</p><span class="seasonal-preview-cta">Explore Collection →</span></div><div class="wide owner-actions"><button class="btn primary" type="submit">Save Campaign</button><button class="btn ghost sm" type="button" data-click="seasonal-restore">Restore previous published version</button></div></form><p class="owner-mini">Publishing backs up the previous seasonal configuration in the same owner-only content table. Restore affects the entire seasonal list. Preview is illustrative; verify the live site before sharing.</p></section>`;
}
function contentView(){const dict=Object.fromEntries(data.content.map(x=>[x.key,x.value]));return `${visualPreview(dict)}<section class="owner-section"><h2>Edit website text</h2><p>Edit homepage, sports, businesses and Customer Favorites copy here. Changes are available to visitors after refresh. Only approved administrators can modify these fields.</p><form data-form="content"><div class="owner-input-grid">${CONTENT_KEYS.map(([key,label,help])=>`<div class="${['hero_description','about_text','hero_title','sports_intro','sports_section_description','business_intro','business_section_description','favorites_description'].includes(key)?'wide':''}"><label class="form-label" for="edit-${key}">${safe(label)}</label>${['hero_description','about_text','hero_title','sports_intro','sports_section_description','business_intro','business_section_description','favorites_description'].includes(key)?`<textarea id="edit-${key}" class="textarea" rows="3" name="${key}" maxlength="1500">${safe(dict[key]||'')}</textarea>`:`<input id="edit-${key}" class="field" name="${key}" maxlength="350" value="${safe(dict[key]||'')}">`}<div class="owner-mini">${safe(help)}</div></div>`).join('')}</div><div class="owner-actions"><button class="btn primary" type="submit">Publish Website Text</button></div></form></section>${favoritesEditor(dict)}<section class="owner-section"><h2>Photo Library & Homepage Editor</h2><p>Upload JPG, PNG or WebP photos (up to 5 MB). Uploaded photos are publicly viewable. Do not upload customer artwork or private files. Copy an uploaded photo URL into the Homepage showcase photo URL field above, then publish.</p><form data-form="upload-site-photo" class="owner-input-grid"><div class="wide"><label class="form-label">SELECT PUBLIC WEBSITE PHOTO</label><input class="field" name="photo" type="file" accept="image/jpeg,image/png,image/webp" required></div><div class="wide"><button class="btn primary">Upload to Photo Library</button></div></form><p class="owner-mini" id="photo-upload-result">Only authenticated owners can upload. Image URLs are public. Images use Supabase Storage Free quota.</p><button class="btn ghost sm" data-click="list-site-photos" type="button">Show Uploaded Photos</button><div id="site-photo-list" class="owner-list"></div><div class="owner-actions"><a class="btn ghost sm" href="${STOREFRONT}" target="_blank" rel="noopener noreferrer">Preview Live Website ↗</a></div><p class="owner-mini">Changes publish immediately after Save. Draft staging, drag-and-drop section rearrangement, and automatic image cropping are not included in this upgrade.</p></section><section class="owner-section"><h2>Where do I edit other things?</h2><p>Use <strong>Apparel</strong> for product names, descriptions and garment colors. Use <strong>Customer Favorites</strong> below to select featured products. Sports and business service pages are included in this release; changing their layout requires a code update.</p></section>`}
function contactsView(){return `<section class="owner-section"><h2>Customer relationship manager</h2><p>Private notes and contact information, visible only to approved owner accounts. Quote submissions do not automatically create CRM entries; add them as needed.</p><form data-form="new-contact" class="owner-input-grid"><div><label class="form-label">CUSTOMER NAME</label><input class="field" name="full_name" maxlength="150" required></div><div><label class="form-label">EMAIL</label><input class="field" name="email" type="email" maxlength="250"></div><div><label class="form-label">PHONE</label><input class="field" name="phone" maxlength="45"></div><div><label class="form-label">COMPANY / TEAM</label><input class="field" name="organization" maxlength="160"></div><div class="wide"><label class="form-label">TAGS</label><input class="field" name="tags" maxlength="300" placeholder="School, repeat customer, holiday order"></div><div class="wide"><label class="form-label">PRIVATE NOTES</label><textarea class="textarea" name="internal_notes" rows="2" maxlength="8000"></textarea></div><div class="wide"><button class="btn primary">Add Customer</button></div></form></section><section class="owner-section"><h2>Contacts (${data.contacts.length})</h2>${data.contacts.length?`<div class="owner-list">${data.contacts.map(c=>`<article><form data-form="contact" data-id="${c.id}" class="owner-input-grid"><div><label class="form-label">NAME</label><input class="field" name="full_name" required maxlength="150" value="${safe(c.full_name)}"></div><div><label class="form-label">EMAIL</label><input class="field" name="email" type="email" maxlength="250" value="${safe(c.email)}"></div><div><label class="form-label">PHONE</label><input class="field" name="phone" maxlength="45" value="${safe(c.phone)}"></div><div><label class="form-label">ORGANIZATION</label><input class="field" name="organization" maxlength="160" value="${safe(c.organization)}"></div><div class="wide"><label class="form-label">TAGS</label><input class="field" name="tags" maxlength="300" value="${safe(c.tags)}" placeholder="Team, repeat client, holiday order"></div><div class="wide"><label class="form-label">PRIVATE CUSTOMER NOTES</label><textarea class="textarea" rows="3" name="internal_notes" maxlength="8000">${safe(c.internal_notes)}</textarea></div><div class="wide"><button class="btn primary sm">Save Customer</button> ${c.email?`<a class="btn ghost sm" href="mailto:${encodeURIComponent(c.email)}">Email Customer</a>`:''}</div></form><div class="v4-timeline"><h4>Customer timeline</h4><p><strong>Related records:</strong> ${data.quotes.filter(q=>c.email&&q.email?.toLowerCase()===c.email.toLowerCase()).length} website quotes · ${data.manualOrders.filter(o=>o.contact_id===c.id).length} manual orders · ${data.invoices.filter(i=>i.contact_id===c.id||(c.email&&i.customer_email?.toLowerCase()===c.email.toLowerCase())).length} estimates/invoices. Customer quote matches are based on email; verify identities before using them.</p>${data.activities.filter(a=>a.contact_id===c.id).slice(0,8).map(a=>`<p><strong>${safe(a.channel)} · ${d(a.occurred_at)}</strong> — ${safe(a.summary)}</p>`).join('')||'<p>No recorded interactions yet.</p>'}<form data-form="new-activity" data-id="${c.id}" class="owner-input-grid"><div><label class="form-label">CHANNEL</label><select class="select" name="channel">${options(CHANNELS,'Instagram')}</select></div><div><label class="form-label">DATE</label><input class="field" type="date" name="occurred_on" value="${new Date().toISOString().slice(0,10)}"></div><div class="wide"><label class="form-label">PRIVATE INTERACTION SUMMARY</label><textarea class="textarea" name="summary" rows="2" maxlength="2000" required placeholder="Discussed order details, promised a follow-up…"></textarea></div><div class="wide"><button class="btn ghost sm">Log Conversation</button></div></form></div></article>`).join('')}</div>`:'<p>No customers have been added yet.</p>'}</section>`}
function stockView(){const low=data.stock.filter(s=>s.quantity<=s.reorder_at);return `<section class="owner-section"><h2>Inventory & stock alerts</h2><p>${low.length} SKUs at or below their reorder threshold. Quantities are owner-managed; customer quotes do not automatically subtract inventory.</p>${low.length?`<div class="owner-flag">Attention needed: ${low.map(s=>safe(s.sku)).join(', ')}</div>`:''}<form data-form="new-stock" class="owner-input-grid"><div><label class="form-label">SKU (UNIQUE)</label><input class="field" name="sku" required maxlength="100" placeholder="HOODIE-NAVY-M"></div><div><label class="form-label">PRODUCT</label><select class="select" name="product_id"><option value="">General supply</option>${data.products.map(x=>`<option value="${safe(x.id)}">${safe(x.name)}</option>`).join('')}</select></div><div><label class="form-label">COLOR</label><input class="field" name="color" maxlength="60"></div><div><label class="form-label">SIZE</label><input class="field" name="size" maxlength="40"></div><div><label class="form-label">ON HAND</label><input class="field" name="quantity" type="number" min="0" max="1000000" value="0" required></div><div><label class="form-label">REORDER AT</label><input class="field" name="reorder_at" type="number" min="0" max="1000000" value="5" required></div><div class="wide"><button class="btn primary">Add Stock Item</button></div></form></section><section class="owner-section"><h2>Current inventory (${data.stock.length} SKUs)</h2>${data.stock.length?`<div class="owner-list">${data.stock.map(s=>`<article><form data-form="stock" data-id="${s.id}" class="owner-input-grid"><div class="wide"><h3>${safe(s.sku)} ${s.quantity<=s.reorder_at?badge('LOW STOCK'):''}</h3><p>${safe(s.color)} ${safe(s.size)}</p></div><div><label class="form-label">ON HAND</label><input class="field" name="quantity" type="number" min="0" max="1000000" value="${s.quantity}" required></div><div><label class="form-label">REORDER AT</label><input class="field" name="reorder_at" type="number" min="0" max="1000000" value="${s.reorder_at}" required></div><div class="wide"><label class="form-label">SUPPLIER</label><input class="field" name="supplier" maxlength="200" value="${safe(s.supplier)}"></div><div class="wide"><label class="form-label">STOCK NOTES</label><textarea name="internal_notes" class="textarea" rows="2" maxlength="1500">${safe(s.internal_notes)}</textarea></div><div class="wide"><button class="btn primary sm">Update Stock</button></div></form></article>`).join('')}</div>`:'<p>No stock items have been entered.</p>'}</section>`}
const usd=n=>'$'+Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function invoiceNumber(){return 'PA-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-9)}
function invoiceItems(text){const raw=String(text||'').trim().split(/\n/).filter(x=>x.trim());if(!raw.length||raw.length>50)throw Error('Enter 1–50 invoice items.');return raw.map(line=>{const parts=line.split('|').map(x=>x.trim());if(parts.length!==3)throw Error('Each item needs: Description | Quantity | Unit price.');const [description,q,price]=parts,quantity=Number(q),unit_price=Number(price);if(!description||description.length>250||!Number.isSafeInteger(quantity)||quantity<=0||quantity>100000||!Number.isFinite(unit_price)||unit_price<0||unit_price>1000000)throw Error('Check the item description, quantity, and price.');return {description,quantity,unit_price:Math.round(unit_price*100)/100}})}
function invoicesView(filter='all'){const visibleInvoices=filter==='Estimate'?data.invoices.filter(i=>i.document_type==='Estimate'):data.invoices;return `<section class="owner-section"><h2>${filter==='Estimate'?'Estimates · Create & Manage':'Create estimate or invoice'}</h2><p>Private pricing. All invoices require Persen Apparel + customer electronic signatures before you send or record payments. PDF is printed locally; email is a manual mail-app draft.</p><form data-form="new-invoice" class="owner-input-grid"><div><label class="form-label">DOCUMENT TYPE</label><select class="select" name="document_type">${options(['Estimate','Invoice'],filter==='Estimate'?'Estimate':'Invoice')}</select></div><div><label class="form-label">CUSTOMER RECORD</label><select class="select" name="contact_id" data-v4-contact-select><option value="">Enter manually</option>${data.contacts.map(c=>`<option value="${c.id}">${safe(c.full_name)}</option>`).join('')}</select></div><div><label class="form-label">CUSTOMER NAME *</label><input class="field" name="customer_name" required maxlength="150"></div><div><label class="form-label">CUSTOMER EMAIL</label><input class="field" name="customer_email" type="email" maxlength="250"></div><div><label class="form-label">COMPANY / TEAM</label><input class="field" name="customer_organization" maxlength="160"></div><div><label class="form-label">DUE / VALID UNTIL</label><input class="field" name="due_date" type="date"></div><div class="wide"><label class="form-label">ITEMS — ONE PER LINE: DESCRIPTION | QTY | UNIT PRICE</label><textarea class="textarea" name="items" rows="5" required placeholder="Custom navy hoodies | 50 | 32.00&#10;Design work | 1 | 25.00"></textarea></div><div><label class="form-label">SHIPPING ($)</label><input class="field" type="number" name="shipping" min="0" max="999999" step="0.01" value="0"></div><div><label class="form-label">TAX AMOUNT ($)</label><input class="field" type="number" name="tax_amount" min="0" max="999999" step="0.01" value="0"></div><div class="wide"><label class="form-label">PUBLIC NOTES</label><textarea class="textarea" name="public_notes" maxlength="1500" rows="2"></textarea></div><div class="wide"><button class="btn primary">Create Document</button></div></form></section><section class="owner-section"><h2>${filter==='Estimate'?'Estimate tracker':'Document tracker'} (${visibleInvoices.length})</h2>${visibleInvoices.length?`<div class="owner-list">${visibleInvoices.map(inv=>{const paid=paymentTotal(inv),due=v4.balance(inv,data.payments),kind=inv.document_type||'Invoice';return `<article><div class="owner-row"><div><h3>${safe(kind)} ${safe(inv.invoice_number)} — ${safe(inv.customer_name)}</h3><p>${d(inv.created_at)} · ${safe(inv.customer_email)} · Total ${usd(inv.total)}</p>${kind==='Invoice'?`<p><strong>Recorded paid: ${usd(paid)} · Balance: ${usd(due)}</strong>${inv.status==='Paid'&&due>0?' · ⚠ Previously marked paid without matching ledger payments':''}</p>`:''}</div>${badge(inv.status)}</div><form class="owner-actions" data-form="invoice-status" data-id="${inv.id}"><label class="owner-mini">STATUS <select class="select" name="status">${options(kind==='Estimate'?['Draft','Sent','Void']:['Draft','Sent','Paid','Void'],inv.status)}</select></label><button class="btn primary sm">Save Status</button><button type="button" class="btn ghost sm" data-click="print-invoice" data-id="${inv.id}">Print / PDF</button><button type="button" class="btn ghost sm" data-click="compose-invoice" data-id="${inv.id}">Compose Email</button>${kind==='Estimate'?`<button type="button" class="btn primary sm" data-click="convert-estimate" data-id="${inv.id}" ${data.invoices.some(x=>x.source_estimate_id===inv.id)?'disabled':''}>${data.invoices.some(x=>x.source_estimate_id===inv.id)?'Already converted':'Convert to Invoice'}</button>`:''}</form>${kind==='Invoice'&&inv.status!=='Void'&&due>0&&PersenAgreements.signed(data.agreements.find(a=>a.invoice_id===inv.id))?`<form data-form="new-payment" data-id="${inv.id}" class="owner-input-grid v4-payment"><div><label class="form-label">RECORD PAYMENT ($)</label><input class="field" type="number" name="amount" min="0.01" max="${due.toFixed(2)}" step="0.01" required placeholder="Up to ${due.toFixed(2)}"></div><div><label class="form-label">METHOD</label><select class="select" name="method">${options(PAYMENT_METHODS,'Other')}</select></div><div><label class="form-label">DATE RECEIVED</label><input class="field" type="date" name="received_on" value="${new Date().toISOString().slice(0,10)}" required></div><div><label class="form-label">REFERENCE / NOTE</label><input class="field" name="notes" maxlength="500" placeholder="Check # or transaction reference"></div><div class="wide"><button class="btn ghost sm">Record Payment (manual)</button></div></form>`:''}${kind==='Invoice'&&paid>0?`<details><summary class="owner-mini">Payment history (${data.payments.filter(p=>p.invoice_id===inv.id).length})</summary><div class="v4-timeline">${data.payments.filter(p=>p.invoice_id===inv.id).map(p=>`<p>${safe(p.received_on)} · ${usd(p.amount)} · ${safe(p.method)} ${safe(p.notes)}</p>`).join('')}</div></details>`:''}${agreementPanel(inv)}</article>`}).join('')}</div>`:'<p>No documents created yet.</p>'}</section>`}
function guestQuotesView(){return `<section class="owner-section"><h2>Guest Quote Requests (${data.guestQuotes.length})</h2><p>Verified website submissions from visitors without accounts. These need manual customer follow-up. They are not automatically linked to registered customer accounts.</p>${data.guestQuotesIssue?`<div class="owner-flag">Guest quote service not configured: ${safe(data.guestQuotesIssue)}. Apply supabase-v5-guest-quotes.sql if enabling this feature.</div>`:''}${data.guestQuotes.length?`<div class="owner-list">${data.guestQuotes.map(x=>`<article><h3>${safe(x.name)} · ${safe(x.category)}</h3><p>${safe(x.email)} · Qty ${safe(x.quantity)} · ${d(x.created_at)}</p><p style="white-space:pre-wrap">${safe(x.details)}</p><form data-form="v5-guest-quote-status" data-id="${safe(x.id)}" class="owner-actions"><select name="status" class="select">${options(QUOTE_STATUSES,x.status)}</select><button class="btn primary sm">Save Status</button><a class="btn ghost sm" href="mailto:${encodeURIComponent(x.email)}?subject=${encodeURIComponent('Your Persen Apparel custom quote request')}">Reply by email</a></form></article>`).join('')}</div>`:'<p>No guest website inquiries yet.</p>'}</section>`}
function agreementPanel(inv){
 if(inv.document_type==='Estimate')return '';
 if(data.agreementsIssue)return `<div class="owner-flag"><strong>Agreements not configured:</strong> ${safe(data.agreementsIssue)}. Apply supabase-v5-agreements.sql in staging before collecting invoice signatures.</div>`;
 const a=data.agreements.find(x=>x.invoice_id===inv.id),ok=PersenAgreements.signed(a);
 if(!a)return `<div class="v5-agreement"><h4>Two-party invoice agreement · Required</h4><p>Create the locked agreement before sending this invoice. The customer must sign in with a confirmed account using ${safe(inv.customer_email||'their invoice email')}.</p><form data-form="v5-create-agreement" data-id="${safe(inv.id)}"><label class="form-label">AGREEMENT TERMS — REVIEW WITH YOUR LEGAL ADVISER</label><textarea class="textarea" name="terms" rows="4" minlength="20" maxlength="6000" required>${safe(DEFAULT_AGREEMENT_TERMS)}</textarea><label class="form-label"><input type="checkbox" name="reviewed" required> I reviewed the invoice details and agreement text.</label><button type="submit" class="btn primary sm">Lock Invoice & Create Agreement</button></form></div>`;
 return `<div class="v5-agreement"><h4>Two-party invoice agreement ${badge(a.status)}</h4><p>${ok?'Both signatures recorded.':'Invoice cannot be marked Sent/Paid or receive recorded payments until both parties sign.'}</p><p class="owner-mini">Document SHA-256: ${safe(a.snapshot_sha256)}<br>Owner: ${safe(a.owner_name||'Not signed')} · ${safe(a.owner_signed_at||'Pending')}<br>Customer: ${safe(a.customer_name||'Not signed')} · ${safe(a.customer_signed_at||'Pending')}</p>${a.status==='Awaiting Persen Signature'?`<details><summary>Review locked agreement terms before signing</summary><p style="white-space:pre-wrap">${safe(a.agreement_terms)}</p><p>Invoice total: ${usd(a.snapshot?.total)} · Customer: ${safe(a.customer_email)}</p></details><form data-form="v5-owner-sign" data-id="${safe(a.id)}"><label class="form-label">YOUR FULL LEGAL NAME</label><input class="field" name="full_name" minlength="2" maxlength="120" required><label class="form-label"><input type="checkbox" name="consent" required> I agree to sign electronically and accept these exact invoice terms.</label><button class="btn primary sm">Sign as Persen Apparel</button></form>`:''}${a.status==='Awaiting Customer Signature'?`<p>Owner signature complete. Ask your customer to register or sign in using <b>${safe(a.customer_email)}</b>, then open My Account → Invoice Agreements.</p><button type="button" class="btn ghost sm" data-click="v5-invite" data-id="${safe(inv.id)}">Compose Customer Invitation</button>`:''}<button type="button" class="btn ghost sm" data-click="v5-agreement-pdf" data-id="${safe(a.id)}">${ok?'Print Signed Record / PDF':'Print Agreement Preview'}</button>${a.status!=='Voided'?`<button type="button" class="btn ghost sm" data-click="v5-void" data-id="${safe(a.id)}">Void Agreement & Invoice</button>`:''}<details><summary class="owner-mini">Signed terms & audit history</summary><p style="white-space:pre-wrap">${safe(a.agreement_terms)}</p>${(a.invoice_agreement_events||[]).map(e=>`<p class="owner-mini">${safe(e.action)} · ${safe(e.actor_name)} · ${safe(e.happened_at)}</p>`).join('')}</details></div>`;
}
const DEFAULT_AGREEMENT_TERMS=`The customer and Persen Apparel agree that the attached invoice describes the proposed custom apparel services and total amount. Production details, garment availability, artwork approval, schedule, delivery method, cancellation/refund handling and payment timing must be confirmed in writing before work begins. By signing electronically, each party agrees to the exact invoice details and these terms. This signature does not constitute final artwork approval or online payment. Any material change requires a new invoice and new signatures.`;
function paymentTotal(inv){return Math.round(data.payments.filter(p=>p.invoice_id===inv.id).reduce((a,p)=>a+Number(p.amount||0),0)*100)/100}

function tasksView(){const open=(data.tasks||[]).filter(x=>x.status!=='Done');return `<section class="owner-section"><h2>Follow-ups & reminders</h2><p>Plan customer follow-ups, supplier checks, order deadlines and other tasks. These are stored in your private Command Center; automatic push reminders are not enabled.</p><form data-form="new-task" class="owner-input-grid"><div><label class="form-label">TASK *</label><input class="field" name="title" required maxlength="180" placeholder="Follow up on the school hoodie quote"></div><div><label class="form-label">CUSTOMER / BUSINESS</label><input class="field" name="customer_name" maxlength="150" placeholder="Optional"></div><div><label class="form-label">DUE DATE</label><input class="field" type="date" name="due_date"></div><div><label class="form-label">PRIORITY</label><select class="select" name="priority">${options(['Normal','High','Urgent'],'Normal')}</select></div><div class="wide"><label class="form-label">PRIVATE NOTES</label><textarea class="textarea" name="notes" rows="2" maxlength="2000"></textarea></div><div class="wide"><button type="submit" class="btn primary">Add Follow-Up</button></div></form></section><section class="owner-section"><h2>Task list (${open.length} open)</h2>${data.tasks?.length?`<div class="owner-list">${data.tasks.map(t=>`<article><form data-form="task" data-id="${t.id}" class="owner-input-grid"><div class="wide"><div class="owner-row"><h3>${safe(t.title)}</h3>${badge(t.priority)}</div><p>${safe(t.customer_name)} · Due ${safe(t.due_date||'Whenever ready')}</p></div><div><label class="form-label">STATUS</label><select name="status" class="select">${options(['Open','In progress','Done'],t.status)}</select></div><div><label class="form-label">DUE DATE</label><input type="date" name="due_date" class="field" value="${safe(t.due_date||'')}"></div><div class="wide"><label class="form-label">NOTES</label><textarea name="notes" rows="2" maxlength="2000" class="textarea">${safe(t.notes||'')}</textarea></div><div class="wide"><button class="btn primary sm">Save Follow-Up</button></div></form></article>`).join('')}</div>`:'<div class="owner-empty">No follow-ups yet. Add your first task above.</div>'}</section>`}
function messagesView(){const unread=data.messages.filter(m=>m.status==='New').length;return `<section class="owner-section"><div class="owner-row"><div><h2>Customer support inbox</h2><p>${unread} new messages · messages submitted by signed-in customers. Email notifications are not automatic until the V3 webhook is configured.</p></div><button data-click="refresh" class="btn ghost sm">Refresh</button></div>${data.messages.length?`<div class="owner-list">${data.messages.map(m=>`<article><div class="owner-row"><div><h3>${safe(m.name)} · ${safe(m.email)}</h3><p>${d(m.created_at)} · ${safe(m.id.slice(0,8))}</p></div>${badge(m.status)}</div><p class="owner-detail">${safe(m.body)}</p><form data-form="support-status" data-id="${m.id}" class="owner-input-grid"><div><label class="form-label">STATUS</label><select class="select" name="status">${options(['New','Read','Replied','Closed'],m.status)}</select></div><div><label class="form-label">REPLY BY EMAIL</label><a href="mailto:${encodeURIComponent(m.email)}?subject=Persen%20Apparel%20Support" class="btn ghost sm">Email Customer</a></div><div class="wide"><label class="form-label">PRIVATE NOTES</label><textarea name="internal_notes" class="textarea" rows="2" maxlength="1500">${safe(m.internal_notes)}</textarea></div><div class="wide"><button class="btn primary sm">Update Message</button></div></form></article>`).join('')}</div>`:'<div class="owner-empty">No customer support messages yet.</div>'}</section>`}
function printInvoice(inv){const lines=Array.isArray(inv.line_items)?inv.line_items:[];const w=window.open('','_blank','width=850,height=920');if(!w){msg('Please allow pop-ups to print invoices.');return}const esc=safe;w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(inv.invoice_number)} | Persen Apparel</title><style>body{font:15px Arial,sans-serif;color:#172b42;margin:50px;max-width:900px}header{display:flex;align-items:center;gap:16px;border-bottom:4px solid #174eb5;padding-bottom:18px}header img{width:90px;height:90px}h1{font-size:34px}table{width:100%;border-collapse:collapse;margin:30px 0}th,td{padding:12px;text-align:left;border-bottom:1px solid #d6e0ec}th{background:#eef4fa} .totals{text-align:right;font-size:17px}.total{font-size:27px;font-weight:bold}small{color:#5f6d7c}.note{white-space:pre-wrap}@media print{button{display:none}}</style></head><body><header><img src="${location.origin+location.pathname.replace(/[^/]+$/,'')}assets/persen-logo.png" alt="Persen Apparel logo"><div><strong>PERSEN APPAREL</strong><p>Custom apparel · Long Island, New York<br>luke@persenapparel.com · (631) 644-0633</p></div></header><h1>${esc(inv.document_type||'Invoice').toUpperCase()}</h1><p><strong>${esc(inv.invoice_number)}</strong> &nbsp; ${esc(inv.status)}<br><small>Created ${d(inv.created_at)} · Due ${esc(inv.due_date||'As agreed')}</small></p><p><strong>Bill to:</strong><br>${esc(inv.customer_name)}<br>${esc(inv.customer_organization)}<br>${esc(inv.customer_email)}</p><table><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Amount</th></tr></thead><tbody>${lines.map(l=>`<tr><td>${esc(l.description)}</td><td>${l.quantity}</td><td>${usd(l.unit_price)}</td><td>${usd(l.quantity*l.unit_price)}</td></tr>`).join('')}</tbody></table><div class="totals">Subtotal: ${usd(inv.subtotal)}<br>Shipping: ${usd(inv.shipping)}<br>Tax: ${usd(inv.tax_amount)}<p class="total">Total: ${usd(inv.total)}</p>${inv.document_type!=='Estimate'?`<p>Recorded payments: ${usd(paymentTotal(inv))}<br>Balance: ${usd(v4.balance(inv,data.payments))}</p>`:''}</div><p class="note">${esc(inv.public_notes)}</p><small>Payment instructions must be confirmed directly with Persen Apparel. This is not an online payment link.</small><p><button onclick="window.print()">Print / Save as PDF</button></p></body></html>`);w.document.close()}
function parseColors(raw){const vals=String(raw).split(',').map(x=>x.trim()).filter(Boolean);if(!vals.length||vals.length>12||vals.some(x=>!/^#[0-9a-fA-F]{6}$/.test(x)))throw Error('Enter between 1 and 12 colors, formatted like #101d35.');return vals}
async function saveProduct(form,create=false){const f=new FormData(form),id=create?String(f.get('id')).trim():form.dataset.id;const obj={id,name:String(f.get('name')||'').trim(),category:String(f.get('category')||'').trim(),kind:String(f.get('kind')),description:String(f.get('description')||'').trim(),colors:parseColors(f.get('colors')),sort_order:Number(f.get('sort_order'))||0,active:create?true:!!f.get('active'),updated_at:new Date().toISOString()};if(!obj.name||!obj.category)throw Error('Name and category are required.');if(!create)delete obj.id;await PA.checked(create?PA.db.from('products').insert(obj):PA.db.from('products').update(obj).eq('id',id));msg('Apparel catalog updated.');await refresh()}
async function submit(form){const type=form.dataset.form,f=new FormData(form),now=new Date().toISOString();try{
 if(type==='v5-guest-quote-status'){await PA.checked(PA.db.from('guest_quote_requests').update({status:String(f.get('status')),updated_at:now}).eq('id',form.dataset.id));msg('Guest quote status saved.');}
 else if(type==='v5-create-agreement'){
  if(!f.get('reviewed'))throw Error('Confirm your review of the exact invoice.');
  await PersenAgreements.create(form.dataset.id,String(f.get('terms')||''));msg('Agreement locked. Sign as Persen Apparel next.');
 }
 else if(type==='v5-owner-sign'){
  const a=data.agreements.find(x=>x.id===form.dataset.id);
  if(!a||a.status!=='Awaiting Persen Signature')throw Error('Agreement is not awaiting owner signature.');
  await PersenAgreements.sign(a.id,String(f.get('full_name')||''),!!f.get('consent'));msg('Owner signed. Customer must now sign using a confirmed customer account.');
 }
 else if(type==='seasonal-save'){
 const S=window.PersenSeasonal,dict=Object.fromEntries(data.content.map(x=>[x.key,x.value]));let campaigns=S.parse(dict.seasonal_campaigns_v1);
 const campaign=S.normalize({slug:f.get('slug'),title:f.get('title'),subtitle:f.get('subtitle'),description:f.get('description'),announcement:f.get('announcement'),theme:f.get('theme'),accent:f.get('accent'),background:f.get('background'),start:f.get('start'),end:f.get('end'),imageUrl:f.get('imageUrl'),featuredIds:f.getAll('featuredIds'),published:!!f.get('published'),limited:!!f.get('limited'),homepage:!!f.get('homepage')});
 if(campaign.featuredIds.some(id=>!data.products.some(p=>p.id===id&&p.active)))throw Error('Only active catalog products can be featured.');
 const oldSlug=String(f.get('previousSlug')||'');campaigns=campaigns.filter(x=>x.slug!==oldSlug);if(campaigns.some(x=>x.slug===campaign.slug))throw Error('Another campaign already uses this URL slug.');
 if(campaigns.length>=40)throw Error('Maximum 40 campaigns. Unpublish and replace an old campaign.');campaigns.push(campaign);
 await PA.checked(PA.db.from('site_content').upsert([{key:'seasonal_backup_v1',value:dict.seasonal_campaigns_v1||'[]',updated_at:now},{key:'seasonal_campaigns_v1',value:JSON.stringify(campaigns),updated_at:now}],{onConflict:'key'}));seasonalEditing=campaign.slug;msg('Seasonal campaign saved. Check its preview and live date window.');
 }
 else if(type==='upload-site-photo'){const file=f.get('photo');if(!(file instanceof File)||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024||file.size===0)throw Error('Choose a JPG, PNG or WebP under 5 MB.');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];const path=`site/${crypto.randomUUID()}.${ext}`;const result=await PA.db.storage.from('site-photos').upload(path,file,{contentType:file.type,upsert:false});if(result.error)throw result.error;const url=PA.db.storage.from('site-photos').getPublicUrl(path).data.publicUrl;const field=document.querySelector('[name="hero_photo_url"]');if(field)field.value=url;msg('Photo uploaded. Click Publish Website Text to set it as the homepage image.');return;}
 if(type==='favorites'){const selected=f.getAll('product_id').filter(x=>data.products.some(p=>p.id===x&&p.active));if(selected.length<1||selected.length>4)throw Error('Choose between 1 and 4 active products.');await PA.checked(PA.db.from('site_content').upsert([{key:'favorites_ids',value:selected.join(','),updated_at:now}],{onConflict:'key'}));msg('Customer Favorites published.');}
 else if(type==='content'){const edits=CONTENT_KEYS.map(([key])=>({key,value:String(f.get(key)||'').slice(0,1500),updated_at:now}));await PA.checked(PA.db.from('site_content').upsert(edits,{onConflict:'key'}));msg('Website copy published. Refresh the storefront to see it.')}
 else if(type==='product'||type==='new-product'){await saveProduct(form,type==='new-product');return}
 else if(type==='quote'){await PA.checked(PA.db.from('quote_requests').update({status:String(f.get('status')),updated_at:now}).eq('id',form.dataset.id));msg('Quote status updated.')}
 else if(type==='order'){await PA.checked(PA.db.from('customer_orders').update({status:String(f.get('status')),fulfillment:String(f.get('fulfillment')),tracking_reference:String(f.get('tracking_reference')||'').slice(0,160),internal_notes:String(f.get('internal_notes')||'').slice(0,2500),updated_at:now}).eq('id',form.dataset.id));msg('Order status updated. Customer can see it after refreshing.')}
 else if(type==='new-contact'||type==='contact'){const obj={full_name:String(f.get('full_name')||'').trim().slice(0,150),email:String(f.get('email')||'').trim().slice(0,250),phone:String(f.get('phone')||'').trim().slice(0,45),organization:String(f.get('organization')||'').trim().slice(0,160),internal_notes:String(f.get('internal_notes')||'').slice(0,8000),tags:String(f.get('tags')||'').slice(0,300),updated_at:now};if(!obj.full_name)throw Error('Customer name is required');await PA.checked(type==='new-contact'?PA.db.from('customer_contacts').insert(obj):PA.db.from('customer_contacts').update(obj).eq('id',form.dataset.id));msg('Customer record saved.');}
 else if(type==='new-stock'||type==='stock'){const obj={quantity:Number(f.get('quantity')),reorder_at:Number(f.get('reorder_at')),supplier:String(f.get('supplier')||'').slice(0,200),internal_notes:String(f.get('internal_notes')||'').slice(0,1500),updated_at:now};if(!Number.isSafeInteger(obj.quantity)||obj.quantity<0||!Number.isSafeInteger(obj.reorder_at)||obj.reorder_at<0)throw Error('Enter valid stock quantities.');if(type==='new-stock'){Object.assign(obj,{sku:String(f.get('sku')||'').trim(),product_id:f.get('product_id')||null,color:String(f.get('color')||''),size:String(f.get('size')||'')});}await PA.checked(type==='new-stock'?PA.db.from('stock_items').insert(obj):PA.db.from('stock_items').update(obj).eq('id',form.dataset.id));msg('Inventory updated.');}
 else if(type==='new-invoice'){const items=invoiceItems(f.get('items'));const sub=Math.round(items.reduce((sum,x)=>sum+x.quantity*x.unit_price,0)*100)/100,shipping=Number(f.get('shipping'))||0,tax=Number(f.get('tax_amount'))||0;if(!Number.isFinite(sub+shipping+tax)||shipping<0||tax<0)throw Error('Check amounts.');const inv={document_type:String(f.get('document_type')||'Invoice'),contact_id:f.get('contact_id')||null,invoice_number:invoiceNumber(),customer_name:String(f.get('customer_name')||'').trim().slice(0,150),customer_email:String(f.get('customer_email')||'').trim().slice(0,250),customer_organization:String(f.get('customer_organization')||'').slice(0,160),line_items:items,subtotal:sub,shipping,tax_amount:tax,total:Math.round((sub+shipping+tax)*100)/100,due_date:f.get('due_date')||null,public_notes:String(f.get('public_notes')||'').slice(0,1500)};if(!inv.customer_name)throw Error('Customer name is required.');await PA.checked(PA.db.from('business_invoices').insert(inv));msg('Document created. Open Print / PDF to share it.');}
 else if(type==='invoice-status'){const inv=data.invoices.find(x=>x.id===form.dataset.id),status=String(f.get('status'));if(!inv)throw Error('Document not found');if(inv.document_type!=='Estimate'&&['Sent','Paid'].includes(status)&&!PersenAgreements.signed(data.agreements.find(a=>a.invoice_id===inv.id)))throw Error('Both parties must sign the invoice agreement before it can be sent or paid.');if(status==='Paid'&&(inv.document_type==='Estimate'||v4.balance(inv,data.payments)>0))throw Error('Record all payments before marking an invoice Paid.');if(status==='Void'&&paymentTotal(inv)>0)throw Error('Paid invoices need a documented refund/correction before voiding.');await PA.checked(PA.db.from('business_invoices').update({status,updated_at:now}).eq('id',form.dataset.id));msg('Document status updated.');}
 else if(type==='new-payment'){const inv=data.invoices.find(x=>x.id===form.dataset.id);if(!inv||inv.document_type==='Estimate'||inv.status==='Void')throw Error('Select an active invoice.');if(!PersenAgreements.signed(data.agreements.find(a=>a.invoice_id===inv.id)))throw Error('Both invoice signatures are required before recording payment.');const amount=Number(f.get('amount'));if(!Number.isFinite(amount)||amount<=0||Math.round(amount*100)!==amount*100&&Math.abs(amount*100-Math.round(amount*100))>0.00001||amount>v4.balance(inv,data.payments))throw Error('Payment must be positive, in cents, and no more than the outstanding balance.');await PA.checked(PA.db.from('invoice_payments').insert({invoice_id:inv.id,amount,method:String(f.get('method')),received_on:f.get('received_on'),notes:String(f.get('notes')||'').slice(0,500)}));msg('Payment recorded in the private ledger.');}
 else if(type==='new-activity'){const summary=String(f.get('summary')||'').trim().slice(0,2000);if(!summary)throw Error('Enter a conversation summary');const occurred=f.get('occurred_on');await PA.checked(PA.db.from('customer_activities').insert({contact_id:form.dataset.id,channel:String(f.get('channel')),summary,occurred_at:occurred?occurred+'T12:00:00Z':now}));msg('Customer timeline updated.');}
 else if(type==='new-manual-order'){const customer_name=String(f.get('customer_name')||'').trim().slice(0,150),title=String(f.get('title')||'').trim().slice(0,180),quantity=Number(f.get('quantity'));if(!customer_name||!title||!Number.isSafeInteger(quantity)||quantity<1||quantity>100000)throw Error('Check customer, project, and quantity.');await PA.checked(PA.db.from('manual_business_orders').insert({contact_id:f.get('contact_id')||null,customer_name,title,quantity,status:String(f.get('status')),due_date:f.get('due_date')||null,internal_notes:String(f.get('internal_notes')||'').slice(0,2500)}));msg('Manual order added.');}
 else if(type==='manual-order'){await PA.checked(PA.db.from('manual_business_orders').update({status:String(f.get('status')),due_date:f.get('due_date')||null,internal_notes:String(f.get('internal_notes')||'').slice(0,2500),updated_at:now}).eq('id',form.dataset.id));msg('Manual order updated.');}
 else if(type==='support-status'){await PA.checked(PA.db.from('support_messages').update({status:String(f.get('status')),internal_notes:String(f.get('internal_notes')||'').slice(0,1500),updated_at:now}).eq('id',form.dataset.id));msg('Support message updated.');}
 else if(type==='new-task'){const title=String(f.get('title')||'').trim().slice(0,180);if(!title)throw Error('Task title required');await PA.checked(PA.db.from('business_tasks').insert({title,customer_name:String(f.get('customer_name')||'').slice(0,150),due_date:f.get('due_date')||null,priority:String(f.get('priority')||'Normal'),notes:String(f.get('notes')||'').slice(0,2000)}));msg('Follow-up added.');}
 else if(type==='task'){await PA.checked(PA.db.from('business_tasks').update({status:String(f.get('status')),due_date:f.get('due_date')||null,notes:String(f.get('notes')||'').slice(0,2000),updated_at:now}).eq('id',form.dataset.id));msg('Follow-up updated.');}
 await refresh()
}catch(err){msg('Could not save: '+err.message)}}
root.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id==='owner-login'){if(!PA?.ready)return;const f=new FormData(form);try{await PA.signIn(String(f.get('email')).trim(),String(f.get('password')));authUser=await PA.me();owner=await PA.isAdmin(authUser);if(!owner){await PA.signOut();authUser=null;login('This account does not have owner access. Contact the site owner.');return}await refresh()}catch(err){msg('Could not sign in: '+err.message)}return}if(form.dataset.form&&owner)await submit(form)});
root.addEventListener('change',e=>{const el=e.target;if(!el.matches('[data-v4-contact-select]'))return;const c=data.contacts.find(x=>x.id===el.value),form=el.closest('form');if(!c||!form)return;form.elements.customer_name.value=c.full_name||'';form.elements.customer_email.value=c.email||'';form.elements.customer_organization.value=c.organization||'';});
root.addEventListener('click',async e=>{const b=e.target.closest('[data-click]');if(!b)return;const action=b.dataset.click;if(action==='view'){view=b.dataset.id;render();window.scrollTo({top:0,behavior:'smooth'})}if(action==='seasonal-new'){seasonalEditing='';render();}
 if(action==='seasonal-edit'){seasonalEditing=b.dataset.id;render();}
 if(action==='seasonal-preset'){seasonalEditing='';render();const sel=root.querySelector('#seasonal-theme'),form=root.querySelector('[data-form="seasonal-save"]');if(sel&&form){sel.value=b.dataset.id;const preset=PersenSeasonal.THEMES[b.dataset.id];form.elements.accent.value=preset.accent;form.elements.background.value=preset.background;form.elements.title.value=preset.label+' Collection';form.elements.slug.value=PersenSeasonal.slug(preset.label+'-collection');form.elements.subtitle.value='A seasonal collection from Persen Apparel, available by custom quote.';const preview=root.querySelector('.seasonal-preview');if(preview){preview.style.setProperty('--season-accent',preset.accent);preview.style.setProperty('--season-bg',preset.background);preview.querySelector('h3').textContent=form.elements.title.value;preview.querySelector('p').textContent=form.elements.subtitle.value;}}}
 if(action==='seasonal-unpublish'||action==='seasonal-restore'){if(!owner)return;try{const dict=Object.fromEntries(data.content.map(x=>[x.key,x.value]));const now=new Date().toISOString();let updated;if(action==='seasonal-restore'){if(!dict.seasonal_backup_v1){msg('No previous version to restore.');return}updated=dict.seasonal_backup_v1;}else{updated=JSON.stringify(PersenSeasonal.parse(dict.seasonal_campaigns_v1).map(x=>x.slug===b.dataset.id?{...x,published:false}:x));}await PA.checked(PA.db.from('site_content').upsert([{key:'seasonal_backup_v1',value:dict.seasonal_campaigns_v1||'[]',updated_at:now},{key:'seasonal_campaigns_v1',value:updated,updated_at:now}],{onConflict:'key'}));msg('Seasonal campaigns updated.');await refresh()}catch(err){msg('Seasonal change failed: '+err.message)}}
 if(action==='refresh'){await refresh();msg('Latest data loaded.')}if(action==='signout'){if(PA?.db)await PA.signOut();authUser=null;owner=false;login()}if(action==='compose-invoice'){const inv=data.invoices.find(x=>x.id===b.dataset.id);if(!inv||!inv.customer_email){msg('This document needs a customer email address.');return}if(inv.document_type!=='Estimate'&&!PersenAgreements.signed(data.agreements.find(a=>a.invoice_id===inv.id))){msg('Create the agreement and collect both signatures before sending this invoice.');return}const note=`Hello ${inv.customer_name},\n\nAttached is ${inv.document_type==='Estimate'?'estimate':'invoice'} ${inv.invoice_number} for ${usd(inv.total)}.\nDue: ${inv.due_date||'as agreed'}.\n\nPlease review the invoice and let us know if you have any questions.\n\nThank you,\nPersen Apparel\n\nIMPORTANT: Attach the PDF invoice before sending this email.`;window.location.href='mailto:'+encodeURIComponent(inv.customer_email)+'?subject='+encodeURIComponent('Persen Apparel '+(inv.document_type==='Estimate'?'estimate':'invoice')+' '+inv.invoice_number)+'&body='+encodeURIComponent(note);msg('Your mail app should open. Attach the document PDF before sending.');}
 if(action==='convert-estimate'){const inv=data.invoices.find(x=>x.id===b.dataset.id);if(!inv||inv.document_type!=='Estimate'){msg('Select an estimate.');return}if(data.invoices.some(x=>x.source_estimate_id===inv.id)){msg('This estimate already has an invoice.');return}if(!confirm('Create a draft invoice from this estimate?'))return;try{const copy={document_type:'Invoice',source_estimate_id:inv.id,contact_id:inv.contact_id,invoice_number:invoiceNumber(),customer_name:inv.customer_name,customer_email:inv.customer_email,customer_organization:inv.customer_organization,line_items:inv.line_items,subtotal:inv.subtotal,shipping:inv.shipping,tax_amount:inv.tax_amount,total:inv.total,due_date:null,public_notes:inv.public_notes,status:'Draft'};await PA.checked(PA.db.from('business_invoices').insert(copy));msg('Draft invoice created from estimate.');await refresh()}catch(err){msg('Could not convert estimate: '+err.message)}return}
 if(action==='print-invoice'){const inv=data.invoices.find(x=>x.id===b.dataset.id);if(inv)printInvoice(inv)}if(action==='create-order'){const q=data.quotes.find(x=>x.id===b.dataset.id);if(!q)return;if(!confirm('Create a tracked order for this customer? Only do this after confirming the project with them.'))return;try{await PA.checked(PA.db.from('customer_orders').insert({user_id:q.user_id,quote_id:q.id,title:q.category+' — '+q.name,status:'Received',fulfillment:'To be confirmed'}));msg('Tracked order created.');view='orders';await refresh()}catch(err){msg('Could not create order: '+err.message)}}});
init();

root.addEventListener('click',async e=>{if(!e.target.closest('[data-click="list-site-photos"]')||!owner)return;const el=document.getElementById('site-photo-list');if(!el)return;el.textContent='Loading photos…';const r=await PA.db.storage.from('site-photos').list('site',{limit:100,sortBy:{column:'created_at',order:'desc'}});if(r.error){el.textContent=r.error.message;return;}el.innerHTML=(r.data||[]).filter(x=>/\.(png|jpg|webp)$/i.test(x.name)).map(x=>{const url=PA.db.storage.from('site-photos').getPublicUrl('site/'+x.name).data.publicUrl;return `<article><img src="${safe(url)}" alt="Uploaded website photo" loading="lazy" style="width:180px;max-width:100%;border-radius:12px"><p><input class="field" readonly value="${safe(url)}" aria-label="Photo URL"></p><button class="btn ghost sm" type="button" data-photo-use="${safe(url)}">Use as homepage photo</button> <button class="btn ghost sm" type="button" data-photo-delete="${safe(x.name)}">Delete photo</button></article>`}).join('')||'<p>No photos uploaded yet.</p>';});
root.addEventListener('click',e=>{const b=e.target.closest('[data-photo-use]');if(!b||!owner)return;const field=document.querySelector('[name="hero_photo_url"]');if(field){field.value=b.dataset.photoUse;field.focus();msg('Photo selected. Click Publish Website Text to save.');}});

root.addEventListener('click',async e=>{const b=e.target.closest('[data-photo-delete]');if(!b||!owner)return;const name=b.dataset.photoDelete;if(!/^[a-zA-Z0-9._-]+\.(png|jpg|webp)$/i.test(name))return;if(!confirm('Delete this photo permanently? Remove it from your homepage first if currently in use.'))return;const r=await PA.db.storage.from('site-photos').remove(['site/'+name]);if(r.error){msg('Could not delete photo: '+r.error.message);return;}msg('Photo deleted. Refresh the photo library.');const list=root.querySelector('[data-click="list-site-photos"]');if(list)list.click();});
// V4.2 visual editor: edit local preview, synchronize with the existing RLS-protected content form.
root.addEventListener('input',e=>{const el=e.target.closest('[data-visual-key]');if(!el||!owner)return;const key=el.dataset.visualKey;const input=root.querySelector('[data-form="content"] [name="'+key+'"]');if(input){input.value=el.innerText.replace(/\r/g,'').slice(0, key==='hero_description'||key==='hero_title'?1500:350);}});
root.addEventListener('input',e=>{const el=e.target;if(!owner||!el.matches('[data-form="content"] [name]'))return;const visual=root.querySelector('[data-visual-key="'+el.name+'"]');if(visual&&document.activeElement!==visual)visual.textContent=el.value;if(el.name==='hero_photo_url'){const img=document.getElementById('v42-preview-image'),placeholder=document.getElementById('v42-image-placeholder');if(img&&placeholder){img.src=el.value;img.hidden=!el.value;placeholder.hidden=!!el.value;}}});
root.addEventListener('click',e=>{if(!owner)return;const photo=e.target.closest('[data-photo-use]');if(photo){const img=document.getElementById('v42-preview-image'),placeholder=document.getElementById('v42-image-placeholder');if(img){img.src=photo.dataset.photoUse;img.hidden=false;placeholder.hidden=true;}}if(e.target.closest('[data-click="v42-reset"]')){render();msg('Preview reset to last loaded website content.');}});

// Local, unsaved Seasonal Studio preview updates; publishing still requires owner RLS.
root.addEventListener('input',e=>{const form=e.target.closest('[data-form="seasonal-save"]');if(!form||!owner)return;const preview=form.querySelector('.seasonal-preview');if(!preview)return;preview.style.setProperty('--season-accent',form.elements.accent.value);preview.style.setProperty('--season-bg',form.elements.background.value);preview.querySelector('h3').textContent=form.elements.title.value||'Your seasonal collection';preview.querySelector('p').textContent=form.elements.subtitle.value||'Your seasonal message will appear here.';});

// V5 owner agreement actions. Server RPCs enforce the actual permissions and signing order.
root.addEventListener('click',async e=>{
 const b=e.target.closest('[data-click^="v5-"]');if(!b||!owner)return;
 try{
  const act=b.dataset.click,id=b.dataset.id;
  if(act==='v5-agreement-pdf'){const a=data.agreements.find(x=>x.id===id);if(a)PersenAgreements.print(a);}
  if(act==='v5-invite'){const inv=data.invoices.find(x=>x.id===id);if(!inv)return;
   const link=STOREFRONT+'/#/account';const subject='Please sign your Persen Apparel invoice '+inv.invoice_number;
   const body='Hello '+inv.customer_name+',\n\nPlease review and electronically sign invoice '+inv.invoice_number+' by signing in with this email address at '+link+'. If you do not have an account, you can create one and confirm your email first. Your signed agreement will appear in My Account.\n\nPlease contact us if any invoice details should be changed before signing.\n\nPersen Apparel';
   window.location.href='mailto:'+encodeURIComponent(inv.customer_email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);
   msg('Mail app opened if configured. Send the invitation yourself; no automatic email was delivered.');
  }
  if(act==='v5-void'){const a=data.agreements.find(x=>x.id===id);if(!a||!confirm('Void this agreement and invoice? This cannot be undone. Issue a NEW invoice for revisions.'))return;const reason=prompt('Why is this invoice being voided? (required)');if(reason===null)return;await PersenAgreements.voidAgreement(id,reason);msg('Agreement and invoice voided.');await refresh();}
 }catch(err){msg('Agreement action failed: '+err.message)}
});
